    {
      "@type": "Question",
      "name": "How do I know if a supplier is a manufacturer or a trader?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Ask which manufacturing site produced a specific batch. A manufacturer can answer. A trader frequently cannot, and if the site is unknown to you the quality certification shown may belong to another party entirely."
      }
    },
    {
      "@type": "Question",
      "name": "Is documentation checked at quotation enough?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Documentation accurate at quotation is not automatically accurate at shipment. Sites change, certifications lapse, and a supplier under pressure may substitute material from another source. Verification before shipment is the step most often skipped."
      }
    },
    {
      "@type": "Question",
      "name": "What is the real cost of a rejected consignment?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The purchase price, the freight, the storage, the delay to whatever depended on it, and the cost of starting again. Measured against that, verification is inexpensive."
      }
    }
  ]
